import pytest
from cattrs import BaseConverter
from cattrs.strategies import configure_tagged_union
from dataclasses import dataclass

@dataclass
class A:
    a: int

@dataclass
class B:
    b: str

def test_recursive_type_alias():
    converter = BaseConverter()

    # Python 3.12+ type alias syntax
    type AOrB = A | B
    type AliasAOrB = AOrB
    type RecursiveAliasAOrB = AliasAOrB

    try:
        configure_tagged_union(RecursiveAliasAOrB, converter)
        print("Successfully configured recursive type alias")
    except Exception as e:
        print(f"Failed to configure recursive type alias: {e}")
        raise e

    assert converter.unstructure(A(1), RecursiveAliasAOrB) == {"_type": "A", "a": 1}
    assert converter.structure({"_type": "A", "a": 1}, RecursiveAliasAOrB) == A(1)

if __name__ == "__main__":
    test_recursive_type_alias()
